import { Router } from 'express';
import { authenticate } from '../middleware/authenticate';
import { authorize } from '../middleware/authorize';
import { sendSuccess } from '../utils/response';
import { getModelResults } from '../services/perceptionEvidence.service';
import { ROLES } from '../constants';

const router = Router();
router.use(authenticate);

/**
 * GET /api/v1/ai/models
 * Evaluation results of the CCTV AI models, as generated by
 * perception-service/evaluation/run_all.py (plus benchmark and false-alarm
 * measurements when present). Each part is null until it has been generated.
 * Access: ADMIN, MANAGER
 */
router.get('/models', authorize(ROLES.ADMIN, ROLES.MANAGER), (_req, res) => {
  sendSuccess(res, getModelResults());
});

export default router;
